'use client'

import { useState } from 'react'
import DuplicateGroup from './components/DuplicateGroup'

export default function Home() {
  const [duplicates, setDuplicates] = useState<any[]>([])
  const [scanning, setScanning] = useState(false)

  const scan = async () => {
    setScanning(true)
    setDuplicates([])

    const folder = await window.electronAPI.pickFolder()
    if (!folder) {
      setScanning(false)
      return
    }

    const result = await window.electronAPI.findDuplicates(folder)
    setDuplicates(result)
    setScanning(false)
  }

  return (
      <div style={{ padding: 30, maxWidth: 900, margin: 'auto' }}>
        <h1 style={{ fontSize: 24, marginBottom: 10 }}>
          Duplicate File Finder
        </h1>

        <p style={{ color: '#94a3b8', marginBottom: 20 }}>
          Scan a folder and find duplicate files across all subfolders.
        </p>

        <button onClick={scan} disabled={scanning}>
          {scanning ? 'Scanning…' : 'Scan Folder'}
        </button>

        <div style={{ marginTop: 30 }}>
          {duplicates.length === 0 && !scanning && (
              <p style={{ color: '#64748b' }}>
                No duplicates found yet.
              </p>
          )}

          {duplicates.map((group, i) => (
              <DuplicateGroup
                  key={group.hash}
                  index={i}
                  files={group.files}
              />
          ))}
        </div>
      </div>
  )
}
