'use client'

type FileItem = {
    fullPath: string
    relativePath: string
}

export default function DuplicateGroup({
                                           index,
                                           files
                                       }: {
    index: number
    files: FileItem[]
}) {
    return (
        <div style={styles.card}>
            <div style={styles.header}>
                <span>Duplicate Group {index + 1}</span>
                <span style={styles.badge}>{files.length} files</span>
            </div>

            <div style={styles.list}>
                {files.map(file => (
                    <div key={file.fullPath} style={styles.file}>
                        <div style={styles.icon}>📄</div>
                        <div>
                            <div style={styles.name}>
                                {file.relativePath.split('/').pop()}
                            </div>
                            <div style={styles.path}>{file.relativePath}</div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    )
}

const styles: any = {
    card: {
        background: '#020617',
        border: '1px solid #1e293b',
        borderRadius: 10,
        padding: 16,
        marginBottom: 20
    },
    header: {
        display: 'flex',
        justifyContent: 'space-between',
        marginBottom: 12,
        fontWeight: 600
    },
    badge: {
        background: '#334155',
        padding: '2px 10px',
        borderRadius: 999,
        fontSize: 12
    },
    list: {
        display: 'flex',
        flexDirection: 'column',
        gap: 10
    },
    file: {
        display: 'flex',
        gap: 10,
        background: '#020617',
        border: '1px solid #1e293b',
        borderRadius: 6,
        padding: 8
    },
    icon: {
        fontSize: 18
    },
    name: {
        fontSize: 14,
        fontWeight: 500
    },
    path: {
        fontSize: 12,
        color: '#94a3b8'
    }
}
